  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --teal: #02838D;
      --teal-dark: #026A72;
      --teal-light: #E6F5F6;
      --teal-50: #F0FAFA;
      --charcoal: #231F20;
      --charcoal-light: #3D3839;
      --white: #FFFFFF;
      --gray-50: #F9FAFB;
      --gray-100: #F3F4F6;
      --gray-200: #E5E7EB;
      --gray-300: #D1D5DB;
      --gray-400: #9CA3AF;
      --gray-500: #6B7280;
      --gray-600: #4B5563;
      --coral: #E8735A;
      --coral-dark: #D4603F;
      --amber: #D4930D;
      --amber-light: #FEF3C7;
      --green-light: #ECFDF5;
      --green: #059669;
      --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
      --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
      --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
      --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      color: var(--charcoal);
      background: var(--white);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    a { text-decoration: none; color: inherit; }
    button { cursor: pointer; font-family: inherit; border: none; background: none; }
    ul, ol { list-style: none; }
    img { max-width: 100%; display: block; }

    .container { max-width: 1240px; margin: 0 auto; padding: 0 20px; }

    /* ==================== HEADER ==================== */
    .header {
      background: var(--white);
      border-bottom: 1px solid var(--gray-200);
      position: sticky;
      top: 0;
      z-index: 100;
    }
    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }
    .logo {
      font-size: 1.5rem;
      font-weight: 800;
      color: var(--teal);
      letter-spacing: -0.5px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .logo-icon {
      width: 32px; height: 32px;
      background: var(--teal);
      border-radius: 8px;
      display: flex; align-items: center; justify-content: center;
      color: var(--white);
      font-weight: 800;
      font-size: 1rem;
    }
    .main-nav { display: flex; align-items: center; gap: 4px; }
    .nav-item {
      position: relative;
      padding: 8px 14px;
      font-size: 0.9rem;
      font-weight: 600;
      color: var(--charcoal);
      border-radius: var(--radius-sm);
      transition: background 0.2s, color 0.2s;
      white-space: nowrap;
    }
    .nav-item:hover, .nav-item.active {
      background: var(--teal-light);
      color: var(--teal);
    }
    .nav-item::after {
      content: '';
      display: inline-block;
      width: 0; height: 0;
      border-left: 4px solid transparent;
      border-right: 4px solid transparent;
      border-top: 4px solid currentColor;
      margin-left: 6px;
      vertical-align: middle;
      transition: transform 0.2s;
    }
    .nav-item.active::after { transform: rotate(180deg); }
    .header-actions { display: flex; align-items: center; gap: 12px; }
    .btn-subscribe {
      background: var(--teal);
      color: var(--white);
      padding: 8px 20px;
      border-radius: var(--radius-full);
      font-size: 0.85rem;
      font-weight: 600;
      transition: background 0.2s;
    }
    .btn-subscribe:hover { background: var(--teal-dark); }
    .btn-signin {
      color: var(--teal);
      font-size: 0.85rem;
      font-weight: 600;
      padding: 8px 14px;
      border-radius: var(--radius-full);
      transition: background 0.2s;
    }
    .btn-signin:hover { background: var(--teal-light); }

    /* ==================== MEGA MENU ==================== */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 28px 32px;
      min-width: 600px;
      opacity: 0;
      visibility: hidden;
      transition: opacity 0.25s, visibility 0.25s, transform 0.25s;
      transform: translateX(-50%) translateY(8px);
      z-index: 200;
    }
    .nav-item.active .mega-menu {
      opacity: 1;
      visibility: visible;
      transform: translateX(-50%) translateY(0);
    }
    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 6px;
    }
    .mega-menu-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }
    .mega-menu-grid.cols-4 { grid-template-columns: repeat(4, 1fr); }
    .mega-link {
      display: block;
      padding: 8px 12px;
      font-size: 0.85rem;
      font-weight: 500;
      color: var(--charcoal-light);
      border-radius: var(--radius-sm);
      transition: background 0.15s, color 0.15s;
    }
    .mega-link:hover { background: var(--teal-light); color: var(--teal); }
    .mega-menu-footer {
      margin-top: 16px;
      padding-top: 16px;
      border-top: 1px solid var(--gray-200);
      display: flex;
      gap: 16px;
    }
    .mega-menu-footer .mega-link {
      font-weight: 600;
      color: var(--teal);
    }
    .mega-heading {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--gray-400);
      padding: 8px 12px 4px;
    }

    /* ==================== STATS TICKER ==================== */
    .stats-ticker {
      background: var(--teal);
      overflow: hidden;
      padding: 10px 0;
    }
    .ticker-track {
      display: flex;
      gap: 60px;
      animation: ticker-scroll 25s linear infinite;
      width: max-content;
    }
    .ticker-item {
      display: flex;
      align-items: center;
      gap: 10px;
      color: var(--white);
      font-size: 0.85rem;
      font-weight: 500;
      white-space: nowrap;
      flex-shrink: 0;
    }
    .ticker-item .ticker-icon {
      width: 28px; height: 28px;
      background: rgba(255,255,255,0.15);
      border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
      font-size: 0.8rem;
    }
    .ticker-sep {
      color: rgba(255,255,255,0.25);
      font-size: 1.2rem;
      flex-shrink: 0;
    }
    @keyframes ticker-scroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    /* ==================== HERO ==================== */
    .hero {
      background: linear-gradient(135deg, var(--teal-50) 0%, var(--white) 100%);
      padding: 48px 0;
    }
    .hero-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 48px;
      align-items: center;
    }
    .hero-content {}
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--teal-light);
      color: var(--teal);
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      padding: 6px 14px;
      border-radius: var(--radius-full);
      margin-bottom: 20px;
    }
    .hero-badge-dot {
      width: 6px; height: 6px;
      background: var(--teal);
      border-radius: 50%;
    }
    .hero-title {
      font-size: 2.5rem;
      font-weight: 800;
      line-height: 1.15;
      color: var(--charcoal);
      margin-bottom: 16px;
      letter-spacing: -0.5px;
    }
    .hero-subtitle {
      font-size: 1.1rem;
      color: var(--gray-600);
      line-height: 1.6;
      margin-bottom: 28px;
      max-width: 520px;
    }
    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--teal);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius-full);
      font-size: 0.95rem;
      font-weight: 600;
      transition: background 0.2s, transform 0.15s;
    }
    .hero-cta:hover { background: var(--teal-dark); transform: translateY(-1px); }
    .hero-image {
      background: var(--teal-light);
      border-radius: var(--radius-xl);
      aspect-ratio: 4/3;
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .hero-image-placeholder {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      color: var(--teal);
    }
    .hero-image-placeholder .icon {
      font-size: 4rem;
      opacity: 0.6;
    }
    .hero-challenge-badge {
      position: absolute;
      top: 20px; right: 20px;
      background: var(--coral);
      color: var(--white);
      padding: 10px 16px;
      border-radius: var(--radius-md);
      font-size: 0.75rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.04em;
      box-shadow: var(--shadow-md);
    }

    /* ==================== TRENDING ==================== */
    .trending {
      padding: 56px 0;
      background: var(--white);
    }
    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 28px;
    }
    .section-title {
      font-size: 1.5rem;
      font-weight: 800;
      color: var(--charcoal);
      letter-spacing: -0.3px;
    }
    .section-link {
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--teal);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: gap 0.2s;
    }
    .section-link:hover { gap: 8px; }
    .trending-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 20px;
    }
    .trending-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: box-shadow 0.25s, transform 0.25s;
    }
    .trending-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-3px);
    }
    .trending-card-img {
      aspect-ratio: 16/10;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2rem;
      color: var(--gray-400);
    }
    .trending-card-body { padding: 16px 18px 20px; }
    .trending-card-tag {
      font-size: 0.7rem;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--teal);
      margin-bottom: 8px;
    }
    .trending-card-title {
      font-size: 0.95rem;
      font-weight: 700;
      line-height: 1.4;
      color: var(--charcoal);
    }

    /* ==================== NEWSLETTER CTA ==================== */
    .newsletter-cta {
      padding: 64px 0;
      background: linear-gradient(135deg, var(--teal) 0%, var(--teal-dark) 100%);
    }
    .newsletter-inner {
      text-align: center;
      max-width: 560px;
      margin: 0 auto;
    }
    .newsletter-heading {
      font-size: 2rem;
      font-weight: 800;
      color: var(--white);
      margin-bottom: 12px;
      letter-spacing: -0.3px;
    }
    .newsletter-body {
      font-size: 1rem;
      color: rgba(255,255,255,0.85);
      margin-bottom: 28px;
      line-height: 1.6;
    }
    .newsletter-form {
      display: flex;
      gap: 10px;
      max-width: 440px;
      margin: 0 auto 12px;
    }
    .newsletter-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid rgba(255,255,255,0.3);
      border-radius: var(--radius-full);
      background: rgba(255,255,255,0.12);
      color: var(--white);
      font-size: 0.9rem;
      font-family: inherit;
      outline: none;
      transition: border-color 0.2s, background 0.2s;
    }
    .newsletter-input::placeholder { color: rgba(255,255,255,0.55); }
    .newsletter-input:focus { border-color: var(--white); background: rgba(255,255,255,0.18); }
    .newsletter-btn {
      background: var(--coral);
      color: var(--white);
      padding: 14px 28px;
      border-radius: var(--radius-full);
      font-size: 0.9rem;
      font-weight: 700;
      white-space: nowrap;
      transition: background 0.2s, transform 0.15s;
    }
    .newsletter-btn:hover { background: var(--coral-dark); transform: translateY(-1px); }
    .newsletter-privacy {
      font-size: 0.78rem;
      color: rgba(255,255,255,0.6);
    }

    /* ==================== HEALTH TOPICS ==================== */
    .health-topics {
      padding: 56px 0;
      background: var(--gray-50);
    }
    .topics-carousel-wrap {
      position: relative;
    }
    .topics-carousel {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      padding: 8px 4px 16px;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }
    .topics-carousel::-webkit-scrollbar { display: none; }
    .topic-card {
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      width: 140px;
      cursor: pointer;
    }
    .topic-circle {
      width: 110px; height: 110px;
      border-radius: 50%;
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2.4rem;
      transition: transform 0.25s, box-shadow 0.25s;
      border: 3px solid transparent;
    }
    .topic-card:hover .topic-circle {
      transform: scale(1.06);
      box-shadow: var(--shadow-lg);
      border-color: var(--teal);
    }
    .topic-label {
      font-size: 0.82rem;
      font-weight: 600;
      text-align: center;
      color: var(--charcoal);
    }
    .carousel-arrow {
      position: absolute;
      top: 50%;
      transform: translateY(-50%);
      width: 40px; height: 40px;
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: var(--shadow-md);
      z-index: 5;
      transition: background 0.2s, box-shadow 0.2s;
      font-size: 1rem;
      color: var(--charcoal);
    }
    .carousel-arrow:hover { background: var(--teal-light); box-shadow: var(--shadow-lg); }
    .carousel-arrow.left { left: -12px; }
    .carousel-arrow.right { right: -12px; }

    /* ==================== HEALTH TOOLS ==================== */
    .health-tools {
      padding: 56px 0;
      background: var(--white);
    }
    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 24px;
    }
    .tool-section {
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 28px;
      transition: box-shadow 0.25s;
    }
    .tool-section:hover { box-shadow: var(--shadow-md); }
    .tool-section-header { margin-bottom: 20px; }
    .tool-section-title {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 6px;
    }
    .tool-section-desc {
      font-size: 0.88rem;
      color: var(--gray-500);
      line-height: 1.5;
    }
    .tool-section-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      margin-top: 14px;
      color: var(--teal);
      font-weight: 600;
      font-size: 0.88rem;
      transition: gap 0.2s;
    }
    .tool-section-cta:hover { gap: 10px; }
    .tool-list { display: flex; flex-direction: column; gap: 12px; }
    .tool-item {
      display: flex;
      align-items: flex-start;
      gap: 14px;
      padding: 14px;
      border-radius: var(--radius-md);
      background: var(--gray-50);
      transition: background 0.2s;
    }
    .tool-item:hover { background: var(--teal-50); }
    .tool-icon {
      width: 40px; height: 40px;
      border-radius: var(--radius-sm);
      background: var(--teal-light);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 1.1rem;
      flex-shrink: 0;
    }
    .tool-info { flex: 1; }
    .tool-name {
      font-size: 0.88rem;
      font-weight: 700;
      color: var(--charcoal);
      margin-bottom: 2px;
    }
    .tool-desc {
      font-size: 0.78rem;
      color: var(--gray-500);
      line-height: 1.4;
    }
    .tool-cta-sm {
      display: inline-flex;
      align-items: center;
      gap: 4px;
      margin-top: 8px;
      color: var(--teal);
      font-weight: 600;
      font-size: 0.78rem;
    }

    /* ==================== RECOMMENDED READS ==================== */
    .recommended-reads {
      padding: 56px 0;
      background: var(--gray-50);
    }
    .reads-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 28px;
      overflow-x: auto;
      -ms-overflow-style: none;
      scrollbar-width: none;
    }
    .reads-tabs::-webkit-scrollbar { display: none; }
    .reads-tab {
      padding: 10px 20px;
      font-size: 0.85rem;
      font-weight: 600;
      color: var(--gray-500);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-full);
      white-space: nowrap;
      transition: all 0.2s;
      cursor: pointer;
    }
    .reads-tab:hover { color: var(--teal); border-color: var(--teal); }
    .reads-tab.active {
      background: var(--teal);
      color: var(--white);
      border-color: var(--teal);
    }
    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 20px;
    }
    .read-card {
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: var(--radius-lg);
      overflow: hidden;
      transition: box-shadow 0.25s, transform 0.25s;
    }
    .read-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-3px);
    }
    .read-card-img {
      aspect-ratio: 16/9;
      background: var(--gray-100);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 2rem;
      color: var(--gray-300);
    }
    .read-card-body { padding: 16px 18px 20px; }
    .read-card-tag {
      font-size: 0.68rem;
      font-weight: 700;
      text-transform: uppercase;
